export function progressiveTax(net){let left=Math.max(0,net),tax=0,previous=0;for(const[cap,rate]of[[150000,0],[300000,.05],[500000,.1],[750000,.15],[1000000,.2],[2000000,.25],[5000000,.3],[Infinity,.35]]){const portion=Math.min(left,cap-previous);tax+=Math.max(0,portion)*rate;left-=portion;previous=cap;if(left<=0)break}return tax}
// Exemptions precede expense allowances; reduce each income row at most once.
export function expenseAfterExemptions(rows,salaryExemption,seniorType,senior){
 let salaryLeft=salaryExemption,seniorLeft=senior;
 const adjusted=rows.map(r=>{let gross=n(r.gross);if(r.taxType==='1'){const used=Math.min(gross,salaryLeft);gross-=used;salaryLeft-=used;}if(r.taxType===seniorType){const used=Math.min(gross,seniorLeft);gross-=used;seniorLeft-=used;}return {...r,gross};});
 const wage=sum(adjusted.filter(r=>['1','2'].includes(r.taxType)),r=>r.gross);
 const rights=adjusted.filter(r=>r.taxType==='3'&&r.subtype==='rights');
 let costs=Math.min(wage*.5,100000)+Math.min(sum(rights.filter(r=>r.method!=='actual'),r=>r.gross)*.5,100000)+sum(rights.filter(r=>r.method==='actual'),r=>Math.min(n(r.costs),r.gross));
 for(const r of adjusted.filter(r=>['5','6','7','8'].includes(r.taxType)))costs+=Math.min(r.gross,r.method==='actual'?n(r.costs):r.gross*(r.taxType==='7'?60:n(r.rate))/100);
 return costs;
}
export function specialDeductions(s){const t=s.tax;
 const solar=t.solarConfirmed&&t.solarConnected>='2026-03-03'&&t.solarConnected<='2026-12-31'?Math.min(200000,n(t.solar)):0;
 const art=t.artConfirmed?Math.min(100000,n(t.art)):0;
 const oldContract=t.homeContract>='2024-04-09'&&t.homeContract<='2025-12-31'&&t.homeStarted>='2024-04-09'&&t.homeStarted<='2025-12-31';
 const home=t.homeConfirmed&&oldContract&&t.homeCompleted>='2026-01-01'&&t.homeCompleted<='2026-12-31'?Math.min(100000,n(t.homeBuild)):0;
 return{solar,art,home};
}
